using System.Security.Cryptography.X509Certificates;
using Enterprise.Shared.Security.Sso;
using FluentAssertions;
using Testing.Shared;
using Xunit;

namespace Enterprise.Shared.UnitTests.Security.Sso.SamlAssertionConsumerServiceTests;

public class ValidateSamlResponseSignatureShould
{
    [Theory]
    [AutoFakeItEasyData]
    public void Return_True_When_Signature_Is_Valid(SamlAssertionConsumerService sut)
    {
        // Arrange
        var certBase64FilePath = Path.Combine(Directory.GetCurrentDirectory(), "Resources", "sso-sample-cert.cer");
        var certificate = X509CertificateLoader.LoadCertificateFromFile(certBase64FilePath);
        const string SamlResponse =
            "";
        var decodedSamlResponse = sut.VerifyAndDecodeSamlResponse(SamlResponse);

        // Act
        var isSignatureValid = sut.ValidateSamlResponseSignature(decodedSamlResponse, certificate);

        // Assert
        isSignatureValid.Should().BeTrue();
    }
}
